insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_pe_v1'
from (values
('116.26.b.1.A',3,'During a sixth-grade warm-up, a student links a skip, a gallop and a slide in one smooth pattern. This is a combination of...','["locomotor skills", "manipulative skills", "rest periods", "fitness tests"]'::jsonb,0,'Skipping, galloping and sliding are all ways of traveling.','original'),
('116.26.b.1.A',3,'Which choice lists only locomotor skills?','["throw, catch and kick", "hop, leap and slide", "dribble, strike and volley", "stretch, bend and twist"]'::jsonb,1,'Locomotor skills move the body from place to place.','original'),
('116.26.b.1.B',3,'A safe landing from a jump begins with...','["locking the knees straight", "landing on the heels only", "bending the knees to absorb force", "holding your breath"]'::jsonb,2,'Soft, bent knees spread out the impact.','original'),
('116.26.b.1.B',3,'To jump higher for a rebound, a player should...','["lean backward", "keep the arms at the sides", "take off from one flat foot only", "swing the arms up while pushing off the floor with both legs"]'::jsonb,3,'Arms and legs work together to create lift.','original'),
('116.26.b.2.A',3,'Which helps a performer keep balance during a quick stop?','["lowering the center of gravity with a wide base", "leaning far forward", "standing tall on tiptoes", "closing the eyes"]'::jsonb,0,'A low center and wide base improve stability.','original'),
('116.26.b.2.A',3,'A balance is easiest to hold when the body''s weight is...','["above the shoulders only", "centered over the base of support", "shifting every second", "outside the feet"]'::jsonb,1,'Weight over the base prevents tipping.','original'),
('116.26.b.2.B',3,'In a ready stance for defense, the feet are...','["together with knees locked", "crossed over", "about shoulder-width apart with knees bent", "pointed backward"]'::jsonb,2,'This position allows fast movement in any direction.','original'),
('116.26.b.2.B',3,'A good defensive slide keeps the...','["eyes on the floor", "arms behind the back", "heels clicking together", "feet from crossing"]'::jsonb,3,'Crossing the feet slows the defender.','original'),
('116.26.b.3.A',3,'To throw to a moving receiver, a player should aim...','["slightly ahead of where the receiver is going", "directly behind the receiver", "at the ground", "at the receiver''s feet"]'::jsonb,0,'A lead pass lets the receiver and ball meet.','original'),
('116.26.b.3.A',3,'A correct overhand throw includes...','["facing the target squarely with locked elbows", "stepping with the foot opposite the throwing arm", "keeping both feet still", "stepping with the same-side foot"]'::jsonb,1,'Opposite-foot steps add power.','original'),
('116.26.b.3.B',3,'To catch a high pass, a player should...','["keep palms flat and stiff", "catch with the pinky fingers together", "reach up with thumbs together and give with the ball", "turn away and swat at it"]'::jsonb,2,'Soft hands absorb the force.','original'),
('116.26.b.3.B',3,'For a low pass below the waist, hands should...','["point up with thumbs together", "stay in the pockets", "form a flat wall", "point down with pinkies together"]'::jsonb,3,'Hands match the level of the pass.','original'),
('116.26.b.3.C',3,'A good dribbling move for changing direction is to...','["keep the ball low and use the hand on the side away from the defender", "watch only the ball", "carry the ball", "slap the ball high"]'::jsonb,0,'Protecting the ball keeps it away from a defender.','original'),
('116.26.b.3.C',3,'When hand dribbling, a player pushes the ball with...','["a closed fist", "the finger pads", "the palm", "the wrist only"]'::jsonb,1,'Finger pads give control.','original'),
('116.26.b.3.D',3,'In soccer dribbling, the ball is kept under control by using...','["using only the toe", "hard kicks every step", "light touches with the inside and outside of the foot", "stepping on the ball"]'::jsonb,2,'Small touches keep the ball close.','original'),
('116.26.b.3.D',3,'When changing speed while foot dribbling, a player should...','["kick as hard as possible", "stop moving the feet", "always run past the ball", "push the ball farther ahead to speed up and use shorter touches to slow down"]'::jsonb,3,'Touch length controls pace.','original'),
('116.26.b.3.E',3,'A punt is performed by...','["dropping the ball and kicking it with the top of the foot before it hits the ground", "rolling the ball and kicking it", "tossing it and swatting with the hand", "throwing the ball and hitting it with the head"]'::jsonb,0,'A punt is a kick of a dropped ball.','original'),
('116.26.b.3.E',3,'For an accurate instep kick, the plant foot should be...','["behind the ball", "beside the ball and pointed at the target", "pointed away from the target", "far in front of the ball"]'::jsonb,1,'The plant foot guides direction.','original'),
('116.26.b.3.F',3,'In a forearm pass, the platform is made by...','["holding the hands open like a bowl", "clapping the hands", "joining the forearms together with arms straight", "keeping the elbows bent and apart"]'::jsonb,2,'A flat platform controls the ball.','original'),
('116.26.b.3.F',3,'To volley the ball to a target, the legs should...','["stay locked", "stand on tiptoes", "cross over", "bend and extend as the arms swing to meet the ball"]'::jsonb,3,'Leg drive adds control and power.','original'),
('116.26.b.3.G',3,'When striking a pitched ball with a bat, the weight should shift...','["from the back foot to the front foot", "to the back heel", "off the ground", "to the toes of the back foot only"]'::jsonb,0,'Weight transfer adds force.','original'),
('116.26.b.3.G',3,'To strike with accuracy, a player should keep the eyes on...','["the bat", "the object until contact", "the ground", "the crowd"]'::jsonb,1,'Watching the object improves timing.','original'),
('116.26.b.3.H',3,'A jump rope routine at this level can include...','["only standing", "only walking", "double unders, crossovers and rhythm changes", "no rope"]'::jsonb,2,'Advanced skills increase the challenge.','original'),
('116.26.b.3.H',3,'To keep a jump rope routine smooth, a jumper should...','["use the whole arm", "land flat footed", "swing from the shoulders", "turn the rope with the wrists and stay on the balls of the feet"]'::jsonb,3,'Small wrist turns save energy.','original'),
('116.26.b.4.A',3,'Closing space on an opponent means...','["moving toward the player to reduce time and room", "standing still", "moving away from the player", "leaving the field"]'::jsonb,0,'Closing space limits an opponent''s options.','original'),
('116.26.b.4.A',3,'Using open space on offense means...','["hiding behind the goal", "moving into an area with no defenders", "standing next to the defender", "staying behind a defender"]'::jsonb,1,'Open space gives a better chance to receive the ball.','original'),
('116.26.b.4.B',3,'With a long-handled implement such as a hockey stick, force comes from...','["holding it with one hand at the top", "only the fingers", "rotating the hips and shoulders through the swing", "not moving the body"]'::jsonb,2,'The body''s rotation transfers power to the implement.','original'),
('116.26.b.4.B',3,'To change the direction of a ball struck with a long-handled implement, a player changes the...','["color of the ball", "shoe type", "grip length only to zero", "angle of the implement face at contact"]'::jsonb,3,'The face angle sends the object.','original'),
('116.26.b.5',3,'A line dance is a rhythmic activity in which participants...','["repeat steps in time with music in lines", "play defense", "only run laps", "race one another"]'::jsonb,0,'Rhythmic activities match movement to a beat.','original'),
('116.26.b.5',3,'A person who keeps the beat in a rhythmic activity is...','["ignoring the music", "moving steps to a steady pulse", "walking randomly", "playing a game of tag"]'::jsonb,1,'Beat awareness helps coordination.','original'),
('116.26.b.6.A',3,'In a net or wall game, a good offensive strategy is to...','["hit right at the opponent", "always hit softly", "hit the ball into open space away from opponents", "stand still"]'::jsonb,2,'Placement beats power.','original'),
('116.26.b.6.A',3,'In an invasion game such as basketball, a defender helps the team by...','["leaving the court", "standing behind the offense", "waiting on the sideline", "staying between the opponent and the goal"]'::jsonb,3,'Positioning protects the goal.','original'),
('116.26.b.6.B',3,'A game skill combination in soccer could be...','["dribble, pass and then shoot", "walk the ball out", "only shoot", "stand and watch"]'::jsonb,0,'Skills are linked during play.','original'),
('116.26.b.6.B',3,'A smooth sequence in volleyball is...','["set only", "pass, set, then spike", "catch and hold", "spike, serve, rest"]'::jsonb,1,'The sequence moves the ball to attack.','original'),
('116.26.b.6.C',3,'Appropriate sporting behavior toward an official includes...','["shouting about every call", "refusing to play", "accepting a call without arguing", "ignoring the rules"]'::jsonb,2,'Respecting officials is part of fair play.','original'),
('116.26.b.6.C',3,'A good sport after a loss...','["quits the team", "blames teammates", "argues with officials", "congratulates the opponents"]'::jsonb,3,'Good sports show respect.','original'),
('116.26.b.7',3,'Orienteering is an outdoor activity that uses a...','["map and compass to find checkpoints", "stopwatch only", "mat and ropes", "racket and net"]'::jsonb,0,'Navigation skills guide the course.','original'),
('116.26.b.7',3,'For a safe hike, a good strategy is to...','["wear sandals on rocky trails", "tell someone your route and carry water", "skip water", "go alone without telling anyone"]'::jsonb,1,'Planning prevents emergencies.','original'),
('116.26.b.8.A',3,'A long-term benefit of regular moderate to vigorous activity is...','["less energy", "weaker bones", "a stronger heart and lower risk of disease", "a weaker heart"]'::jsonb,2,'Exercise strengthens the body over time.','original'),
('116.26.b.8.A',3,'Regular physical activity can also improve...','["only height", "nothing", "only eyesight", "mood and sleep"]'::jsonb,3,'Activity supports mental health too.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_pe_v1'
from (values
('116.26.b.8.B',3,'In the FITT principle, the first T stands for...','["time", "team", "test", "target"]'::jsonb,0,'FITT = frequency, intensity, time, type.','original'),
('116.26.b.8.B',3,'In FITT, ''intensity'' describes...','["how often you work out", "how hard you work", "how long you work out", "what kind of exercise you do"]'::jsonb,1,'Intensity is effort level.','original'),
('116.26.b.8.C',3,'A sixth grader holds a plank for as long as possible to test the core. Which health-related fitness component does this measure?','["agility", "coordination", "muscular endurance", "reaction time"]'::jsonb,2,'Health-related components include cardiorespiratory endurance, muscular strength, muscular endurance, flexibility and body composition.','original'),
('116.26.b.8.C',3,'A goalie must react quickly to a shot. Which skill-related fitness component is most used?','["flexibility", "muscular strength", "body composition", "reaction time"]'::jsonb,3,'Skill-related components include agility, balance, coordination, power, reaction time and speed.','original'),
('116.26.b.9.A',3,'A good fitness goal is...','["specific, measurable and realistic", "impossible", "unwritten and unmeasured", "vague and huge"]'::jsonb,0,'SMART goals guide progress.','original'),
('116.26.b.9.A',3,'An individual fitness plan should be built around...','["a friend''s goals only", "personal goals and current fitness level", "no goals", "random choices"]'::jsonb,1,'Plans must match the person.','original'),
('116.26.b.9.B',3,'After a fitness assessment, a student should...','["compare only with others", "ignore the scores", "look for weak areas and set strategies to improve", "throw away the results"]'::jsonb,2,'Results show what to work on.','original'),
('116.26.b.9.B',3,'If a student''s flexibility score is low, a good strategy is to...','["only lift heavy weights", "skip warm-ups", "avoid all movement", "add regular stretching"]'::jsonb,3,'Flexibility improves with stretching.','original'),
('116.26.b.10.A',3,'Which macronutrient is the body''s main source of quick energy?','["carbohydrates", "fiber", "vitamins", "water"]'::jsonb,0,'Carbs fuel activity.','original'),
('116.26.b.10.A',3,'Proteins help the body mainly by...','["providing zero nutrients", "building and repairing muscle", "storing energy only", "cooling the body"]'::jsonb,1,'Protein builds tissue.','original'),
('116.26.b.10.B',3,'Which weather condition increases the risk of dehydration during exercise?','["cold and calm", "cool dry air", "high temperature and high humidity", "light drizzle in the shade"]'::jsonb,2,'Heat and humidity raise sweating.','original'),
('116.26.b.10.B',3,'A sign of dehydration is...','["clear urine", "high energy", "a slow heartbeat only", "dark urine and a dry mouth"]'::jsonb,3,'The body is low on fluid.','original'),
('116.26.b.11.A',3,'Before an activity such as inline skating, students should...','["put on a helmet and pads without being told", "wait to be reminded", "wear loose sandals", "skip safety gear"]'::jsonb,0,'Choosing proper gear is a responsibility.','original'),
('116.26.b.11.A',3,'Proper attire for a PE class includes...','["heavy winter coats indoors", "athletic shoes and clothing that allows free movement", "jeans and dress shoes", "sandals"]'::jsonb,1,'Right clothing prevents injury.','original'),
('116.26.b.11.B',3,'A safety precaution for outdoor cycling is to...','["ride with headphones loud", "ride at night without lights", "obey traffic rules and wear a helmet", "ignore stop signs"]'::jsonb,2,'Cycling safety protects the rider.','original'),
('116.26.b.11.B',3,'A sun safety step during outdoor activity is...','["staying in direct sun without breaks", "using no water", "wearing only dark tank tops", "applying sunscreen and wearing a hat"]'::jsonb,3,'Sun protection prevents burns.','original'),
('116.26.b.12.A',3,'Taking responsibility for personal actions means...','["admitting your choices affect others and owning them", "hiding mistakes", "ignoring teammates", "blaming others"]'::jsonb,0,'Accountability builds trust.','original'),
('116.26.b.12.A',3,'A responsible student in a group activity...','["takes all the equipment", "follows rules and shares equipment", "makes fun of others", "ignores the teacher"]'::jsonb,1,'Choices affect the group.','original'),
('116.26.b.12.B',3,'Respecting differences among classmates means...','["only picking friends", "making fun of mistakes", "including everyone and valuing each person''s abilities", "leaving out slower players"]'::jsonb,2,'Respect builds a positive class.','original'),
('116.26.b.12.B',3,'A fair team makes sure...','["only stars play", "weaker players are benched", "boys and girls are separated", "everyone gets a chance to participate"]'::jsonb,3,'Inclusion is respect in action.','original'),
('116.26.b.12.C',3,'Self-control during a heated game means...','["taking a deep breath instead of yelling", "quitting immediately", "throwing equipment", "pushing opponents"]'::jsonb,0,'Managing impulses keeps the game fair.','original'),
('116.26.b.12.C',3,'A student who feels angry after a missed shot should...','["blame a teammate", "pause, breathe and refocus on the next play", "break something", "walk off the court"]'::jsonb,1,'Self-management keeps emotions from taking over.','original'),
('116.26.b.13.A',3,'A socially acceptable way to resolve a conflict over a call is to...','["spread rumors", "stop talking forever", "calmly talk it out or ask the teacher to help", "shout and push"]'::jsonb,2,'Calm talk solves problems.','original'),
('116.26.b.13.A',3,'Conflict resolution usually starts with...','["ignoring the problem", "walking away angry", "blaming one person", "listening to each person''s side"]'::jsonb,3,'Listening comes first.','original'),
('116.26.b.13.B',3,'Effective communication on a team includes...','["using clear words and listening to teammates", "ignoring teammates", "only using insults", "whispering plays"]'::jsonb,0,'Clear talk improves teamwork.','original'),
('116.26.b.13.B',3,'A good call during a game is one that is...','["mumbled", "short, loud and clear", "a secret", "a long speech"]'::jsonb,1,'Teammates need quick information.','original'),
('116.26.b.13.C',3,'Showing empathy to a teammate who made an error means...','["blaming them", "ignoring them", "encouraging them and recognizing their feelings", "laughing"]'::jsonb,2,'Empathy supports others.','original'),
('116.26.b.13.C',3,'A kind response to a classmate who is struggling with a skill is...','["refusing to partner with them", "pointing and laughing", "taking away the equipment", "offering a tip and encouragement"]'::jsonb,3,'Mutual respect helps everyone improve.','original'),
('116.26.b.14',3,'Perseverance in PE means...','["continuing to try even when a skill is hard", "avoiding hard skills", "only doing easy tasks", "quitting at the first mistake"]'::jsonb,0,'Persistence leads to improvement.','original'),
('116.26.b.14',3,'A student shows perseverance by...','["copying a friend", "practicing a skill repeatedly until it improves", "complaining", "giving up after one try"]'::jsonb,1,'Practice builds skill.','original'),
('116.26.b.15',3,'Constructive feedback is feedback that is...','["only criticism", "mean", "specific, helpful and respectful", "vague"]'::jsonb,2,'It helps the performer improve.','original'),
('116.26.b.15',3,'A good way to receive feedback is to...','["ignore it", "argue with the coach", "get angry", "listen, say thanks and try the suggestion"]'::jsonb,3,'Accepting feedback speeds up growth.','original'),
('116.26.b.16.A',3,'A plan to be active using technology might include...','["a fitness app or tracker to log minutes of activity", "a nap reminder", "a snack timer", "a game that requires no movement"]'::jsonb,0,'Technology can help track activity.','original'),
('116.26.b.16.A',3,'Which measure can a fitness tracker display?','["spelling scores", "heart rate", "hair color", "shoe size"]'::jsonb,1,'Heart rate shows exercise intensity.','original'),
('116.26.b.16.B',3,'Taking part in a variety of physical activities helps build...','["boredom", "less energy", "confidence and new skills", "bad habits"]'::jsonb,2,'Trying activities builds self-assurance.','original'),
('116.26.b.16.B',3,'Trying a new physical activity can lead to...','["avoiding movement", "an automatic injury", "losing all motivation", "finding something you enjoy"]'::jsonb,3,'Variety helps people find a lifelong activity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
